<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
<title>Bookkeeping Calculator</title>
<style>
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:#1a1a2e;display:flex;justify-content:center;align-items:center;min-height:100vh;padding:8px}
.phone{background:#0f0f1a;border-radius:36px;width:100%;max-width:400px;height:520px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.06)}
.status-bar{display:flex;justify-content:space-between;align-items:center;padding:10px 24px 2px;color:rgba(255,255,255,.5);font-size:11px;font-weight:600;letter-spacing:.5px}
.header{padding:4px 24px 6px;display:flex;justify-content:space-between;align-items:center}
.header h1{color:rgba(255,255,255,.85);font-size:15px;font-weight:700;letter-spacing:.3px}
.clear-btn{background:rgba(255,255,255,.06);border:none;color:#ff6b6b;font-size:11px;font-weight:700;padding:5px 14px;border-radius:20px;cursor:pointer;transition:all .15s;letter-spacing:.5px}
.clear-btn:hover{background:rgba(255,107,107,.15)}
.clear-btn:active{transform:scale(.95)}
.tape-container{flex:1;overflow-y:auto;padding:4px 24px 8px;display:flex;flex-direction:column;gap:1px;scrollbar-width:none;-ms-overflow-style:none}
.tape-container::-webkit-scrollbar{display:none}
.tape-line{display:flex;justify-content:space-between;align-items:center;font-size:13px;font-family:'SF Mono','Courier New',monospace;padding:3px 0;animation:fadeIn .2s ease}
@keyframes fadeIn{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:translateY(0)}}
.tape-expr{color:rgba(255,255,255,.35);font-size:12px}
.tape-result{color:rgba(255,255,255,.6);font-weight:600;font-size:13px}
.tape-result.positive{color:#51cf66}
.tape-result.negative{color:#ff6b6b}
.tape-divider{height:1px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.08),transparent);margin:4px 0}
.tape-total{display:flex;justify-content:space-between;align-items:center;font-size:14px;font-family:'SF Mono','Courier New',monospace;padding:6px 0;font-weight:700;color:#ffd43b}
.display-area{padding:8px 24px 12px;text-align:right;min-height:80px;display:flex;flex-direction:column;justify-content:flex-end}
.expression{color:rgba(255,255,255,.3);font-size:15px;font-family:'SF Mono','Courier New',monospace;min-height:20px;margin-bottom:4px;word-break:break-all;line-height:1.3}
.current-value{color:#fff;font-size:40px;font-weight:200;font-family:'SF Mono','Courier New',monospace;line-height:1.1;letter-spacing:-1px;transition:font-size .15s}
.current-value.small{font-size:28px}
.buttons{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:6px 14px 20px}
.btn{border:none;border-radius:14px;font-size:20px;font-weight:500;cursor:pointer;display:flex;align-items:center;justify-content:center;height:48px;transition:all .1s;user-select:none;position:relative;overflow:hidden}
.btn::after{content:'';position:absolute;inset:0;background:rgba(255,255,255,0);transition:background .1s}
.btn:active::after{background:rgba(255,255,255,.1)}
.btn:active{transform:scale(.95)}
.btn-num{background:rgba(255,255,255,.08);color:#fff}
.btn-num:hover{background:rgba(255,255,255,.12)}
.btn-op{background:rgba(255,159,67,.15);color:#ff9f43;font-size:22px;font-weight:600}
.btn-op:hover{background:rgba(255,159,67,.25)}
.btn-op.active{background:#ff9f43;color:#0f0f1a}
.btn-func{background:rgba(255,255,255,.04);color:rgba(255,255,255,.7);font-size:16px;font-weight:600}
.btn-func:hover{background:rgba(255,255,255,.08)}
.btn-eq{background:linear-gradient(135deg,#51cf66,#37b24d);color:#fff;font-size:24px;font-weight:700;box-shadow:0 4px 15px rgba(81,207,102,.3)}
.btn-eq:hover{box-shadow:0 4px 20px rgba(81,207,102,.4)}
.btn-zero{grid-column:span 2}
.empty-state{display:flex;flex-direction:column;align-items:center;justify-content:center;flex:1;color:rgba(255,255,255,.15);font-size:12px;gap:6px;padding:20px}
.empty-state svg{opacity:.3}
</style>
</head>
<body>
<div class="phone">
<div class="status-bar"><span>9:41</span><span>⚡ 100%</span></div>
<div class="header">
<h1>📒 Bookkeeping</h1>
<button class="clear-btn" onclick="clearAll()">CLEAR ALL</button>
</div>
<div class="tape-container" id="tape"></div>
<div class="display-area">
<div class="expression" id="expression"></div>
<div class="current-value" id="display">0</div>
</div>
<div class="buttons">
<button class="btn btn-func" onclick="inputClear()">AC</button>
<button class="btn btn-func" onclick="toggleSign()">+/−</button>
<button class="btn btn-func" onclick="inputPercent()">%</button>
<button class="btn btn-op" id="op-div" onclick="inputOp('÷')">÷</button>
<button class="btn btn-num" onclick="inputNum('7')">7</button>
<button class="btn btn-num" onclick="inputNum('8')">8</button>
<button class="btn btn-num" onclick="inputNum('9')">9</button>
<button class="btn btn-op" id="op-mul" onclick="inputOp('×')">×</button>
<button class="btn btn-num" onclick="inputNum('4')">4</button>
<button class="btn btn-num" onclick="inputNum('5')">5</button>
<button class="btn btn-num" onclick="inputNum('6')">6</button>
<button class="btn btn-op" id="op-sub" onclick="inputOp('−')">−</button>
<button class="btn btn-num" onclick="inputNum('1')">1</button>
<button class="btn btn-num" onclick="inputNum('2')">2</button>
<button class="btn btn-num" onclick="inputNum('3')">3</button>
<button class="btn btn-op" id="op-add" onclick="inputOp('+')">+</button>
<button class="btn btn-num btn-zero" onclick="inputNum('0')">0</button>
<button class="btn btn-num" onclick="inputDot()">.</button>
<button class="btn btn-eq" onclick="calculate()">=</button>
</div>
</div>

<script>
let currentInput='0';
let previousValue=null;
let operator=null;
let shouldResetInput=false;
let history=[];
let runningTotal=0;
let expressionStr='';

const displayEl=document.getElementById('display');
const exprEl=document.getElementById('expression');
const tapeEl=document.getElementById('tape');

function formatNumber(n){
if(n==='Error')return'Error';
let num=typeof n==='string'?parseFloat(n):n;
if(isNaN(num))return'0';
let s=num.toFixed(2);
let parts=s.split('.');
parts[0]=parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');
return parts.join('.');
}

function updateDisplay(){
let val=currentInput;
if(val.length>12){
displayEl.classList.add('small');
}else{
displayEl.classList.remove('small');
}
if(val==='Error'){
displayEl.textContent='Error';
}else if(val.includes('.')&&val.endsWith('0')&&!shouldResetInput){
displayEl.textContent=val;
}else{
let n=parseFloat(val);
if(!isNaN(n)&&shouldResetInput){
displayEl.textContent=formatNumber(n);
}else{
displayEl.textContent=val;
}
}
exprEl.textContent=expressionStr;
highlightOp();
}

function highlightOp(){
document.querySelectorAll('.btn-op').forEach(b=>b.classList.remove('active'));
if(operator&&shouldResetInput){
let map={'+':'op-add','−':'op-sub','×':'op-mul','÷':'op-div'};
let el=document.getElementById(map[operator]);
if(el)el.classList.add('active');
}
}

function inputNum(n){
if(currentInput==='Error')currentInput='0';
if(shouldResetInput){
currentInput=n;
shouldResetInput=false;
}else{
if(currentInput==='0'&&n!=='0'){
currentInput=n;
}else if(currentInput==='0'&&n==='0'){
}else{
if(currentInput.replace(/[^0-9]/g,'').length>=12)return;
currentInput+=n;
}
}
updateDisplay();
}

function inputDot(){
if(shouldResetInput){
currentInput='0.';
shouldResetInput=false;
}else if(!currentInput.includes('.')){
currentInput+='.';
}
updateDisplay();
}

function inputOp(op){
if(currentInput==='Error')return;
let cur=parseFloat(currentInput);
if(previousValue!==null&&!shouldResetInput){
let result=compute(previousValue,cur,operator);
if(result==='Error'){
currentInput='Error';
previousValue=null;
operator=null;
expressionStr='';
updateDisplay();
return;
}
currentInput=String(result);
previousValue=result;
expressionStr=formatNumber(result)+' '+op;
}else{
previousValue=cur;
expressionStr=formatNumber(cur)+' '+op;
}
operator=op;
shouldResetInput=true;
updateDisplay();
}

function compute(a,b,op){
switch(op){
case'+':return a+b;
case'−':return a-b;
case'×':return a*b;
case'÷':return b===0?'Error':a/b;
default:return b;
}
}

function calculate(){
if(currentInput==='Error')return;
if(previousValue===null||operator===null)return;
let cur=parseFloat(currentInput);
let result=compute(previousValue,cur,operator);
let fullExpr=formatNumber(previousValue)+' '+operator+' '+formatNumber(cur);
if(result==='Error'){
currentInput='Error';
expressionStr=fullExpr+' =';
previousValue=null;
operator=null;
shouldResetInput=true;
updateDisplay();
return;
}
let rounded=Math.round(result*100)/100;
addTapeEntry(fullExpr,rounded);
runningTotal+=rounded;
expressionStr=fullExpr+' =';
currentInput=String(rounded);
previousValue=null;
operator=null;
shouldResetInput=true;
updateDisplay();
renderTape();
}

function addTapeEntry(expr,result){
history.push({expr,result});
if(history.length>50)history.shift();
}

function renderTape(){
tapeEl.innerHTML='';
if(history.length===0){
tapeEl.innerHTML='<div class="empty-state"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="4" y="2" width="16" height="20" rx="2"/><line x1="8" y1="7" x2="16" y2="7"/><line x1="8" y1="11" x2="16" y2="11"/><line x1="8" y1="15" x2="12" y2="15"/></svg><span>Your calculation tape will appear here</span></div>';
return;
}
history.forEach((item,i)=>{
let line=document.createElement('div');
line.className='tape-line';
let sign=item.result<0?'negative':'positive';
let prefix=item.result>=0?'+':'';
line.innerHTML=`<span class="tape-expr">${item.expr}</span><span class="tape-result ${sign}">${prefix}${formatNumber(item.result)}</span>`;
tapeEl.appendChild(line);
});
let divider=document.createElement('div');
divider.className='tape-divider';
tapeEl.appendChild(divider);
let totalLine=document.createElement('div');
totalLine.className='tape-total';
let tSign=runningTotal<0?'−':'';
totalLine.innerHTML=`<span>Total (${history.length} entries)</span><span>${tSign}${formatNumber(Math.abs(runningTotal))}</span>`;
tapeEl.appendChild(totalLine);
tapeEl.scrollTop=tapeEl.scrollHeight;
}

function inputClear(){
if(currentInput!=='0'&&currentInput!=='Error'&&!shouldResetInput){
currentInput='0';
}else{
currentInput='0';
previousValue=null;
operator=null;
expressionStr='';
shouldResetInput=false;
}
updateDisplay();
}

function clearAll(){
currentInput='0';
previousValue=null;
operator=null;
expressionStr='';
shouldResetInput=false;
history=[];
runningTotal=0;
updateDisplay();
renderTape();
}

function toggleSign(){
if(currentInput==='Error'||currentInput==='0')return;
if(currentInput.startsWith('-')){
currentInput=currentInput.slice(1);
}else{
currentInput='-'+currentInput;
}
updateDisplay();
}

function inputPercent(){
if(currentInput==='Error')return;
let val=parseFloat(currentInput)/100;
val=Math.round(val*10000)/10000;
currentInput=String(val);
shouldResetInput=true;
updateDisplay();
}

// Keyboard support
document.addEventListener('keydown',e=>{
if(e.key>='0'&&e.key<='9')inputNum(e.key);
else if(e.key==='.')inputDot();
else if(e.key==='+')inputOp('+');
else if(e.key==='-')inputOp('−');
else if(e.key==='*')inputOp('×');
else if(e.key==='/'){e.preventDefault();inputOp('÷');}
else if(e.key==='Enter'||e.key==='=')calculate();
else if(e.key==='Escape')inputClear();
else if(e.key==='Backspace'){
if(!shouldResetInput&&currentInput.length>1){
currentInput=currentInput.slice(0,-1);
}else{
currentInput='0';
}
updateDisplay();
}
else if(e.key==='%')inputPercent();
});

renderTape();
updateDisplay();
</script>
</body>
</html>
