<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>Bookkeeping Calculator</title>
<style>
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent;user-select:none}
body{display:flex;justify-content:center;align-items:center;min-height:100vh;background:#1a1a2e;font-family:-apple-system,BlinkMacSystemFont,'Helvetica Neue',sans-serif}
.phone{width:100%;max-width:400px;height:520px;background:#000;border-radius:36px;overflow:hidden;display:flex;flex-direction:column;position:relative;box-shadow:0 20px 60px rgba(0,0,0,.6),inset 0 0 0 2px #333}
.status-bar{height:28px;display:flex;justify-content:space-between;align-items:center;padding:0 24px;color:#fff;font-size:11px;font-weight:600;flex-shrink:0}
.tape{flex:1;overflow-y:auto;padding:4px 20px;display:flex;flex-direction:column;justify-content:flex-end;min-height:0;scrollbar-width:none}
