.tape-line.op{color:#888}
.display{padding:0 20px 6px;flex-shrink:0}
.expression{color:#888;font-size:15px;text-align:right;height:20px;line-height:20px;font-variant-numeric:tabular-nums;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.main-display{color:#fff;font-size:44px;font-weight:300;text-align:right;line-height:1.15;font-variant-numeric:tabular-nums;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;letter-spacing:-.5px}
