</head>
<body>
<div class="phone">
<div class="status-bar"><span>9:41</span><span>⚡ 100%</span></div>
<div class="tape" id="tape"></div>
<div class="display">
<div class="expression" id="expr"></div>
<div class="main-display" id="disp">0</div>
</div>
<div class="controls">
<button class="btn btn-fn" onclick="cClear()">AC</button>
<button class="btn btn-fn" onclick="cSign()">+/−</button>
<button class="btn btn-vat" id="bVatAdd" onclick="cVat('add')">+VAT</button>
<button class="btn btn-op" data-op="/" onclick="cOp('/')">÷</button>

<button class="btn btn-num" onclick="cNum('7')">7</button>
<button class="btn btn-num" onclick="cNum('8')">8</button>
<button class="btn btn-num" onclick="cNum('9')">9</button>
<button class="btn btn-op" data-op="*" onclick="cOp('*')">×</button>

<button class="btn btn-num" onclick="cNum('4')">4</button>
<button class="btn btn-num" onclick="cNum('5')">5</button>
<button class="btn btn-num" onclick="cNum('6')">6</button>
<button class="btn btn-op" data-op="-" onclick="cOp('-')">−</button>

<button class="btn btn-num" onclick="cNum('1')">1</button>
<button class="btn btn-num" onclick="cNum('2')">2</button>
<button class="btn btn-num" onclick="cNum('3')">3</button>
<button class="btn btn-op" data-op="+" onclick="cOp('+')">+</button>

<button class="btn btn-num btn-zero" onclick="cNum('0')">0</button>
<button class="btn btn-num" onclick="cDot()">.</button>
<button class="btn btn-accent" onclick="cEq()">=</button>

<div class="sep"></div>
<button class="btn btn-vat" style="font-size:11px" onclick="cRate(5)">5%</button>
<button class="btn btn-vat" style="font-size:11px" onclick="cRate(10)">10%</button>
<button class="btn btn-vat active" style="font-size:11px" id="bR20" onclick="cRate(20)">20%</button>
<button class="btn btn-vat" style="font-size:10px" onclick="cVat('sub')">−VAT</button>
</div>
<div class="home-ind"></div>
</div>
<script>
let cur='0',prev=null,op=null,fresh=true,vatR=20,hist=[];
const $d=document.getElementById('disp'),$e=document.getElementById('expr'),$t=document.getElementById('tape');

function fmt(n){
  if(n==='Error')return'Error';
  let s=String(n);
  if(s.includes('e'))return parseFloat(n).toExponential(4);
  let p=s.split('.'),i=p[0],d=p[1];
  let neg=i.startsWith('-');if(neg)i=i.slice(1);
  i=i.replace(/\B(?=(\d{3})+(?!\d))/g,',');
  return(neg?'-':'')+i+(d!==undefined?'.'+d:'');
}

function upd(){
  let v=cur;
  if(v!=='Error'&&!v.endsWith('.')){
    let n=parseFloat(v);
    if(!isNaN(n)&&isFinite(n))v=fmt(n);
  }
  $d.textContent=v;
  $d.style.fontSize=v.length>11?'30px':v.length>8?'36px':'44px';
  if(op){
    const sym={'+':'+','-':'−','*':'×','/':'÷'};
    $e.textContent=(prev!==null?fmt(prev):'')+' '+sym[op];
  }else if(!fresh&&hist.length){
    $e.textContent=hist[hist.length-1];
  }else{
    $e.textContent='';
  }
  document.querySelectorAll('.btn-op').forEach(b=>{
    b.classList.toggle('active',op&&b.dataset.op===op&&fresh);
  });
}

function tape(txt,cls){
  hist.push(txt);
  const d=document.createElement('div');
  d.className='tape-line'+(cls?' '+cls:'');
  d.textContent=txt;
  $t.appendChild(d);
  $t.scrollTop=$t.scrollHeight;
}

function calc(a,o,b){
  a=parseFloat(a);b=parseFloat(b);
  if(o==='+')return a+b;if(o==='-')return a-b;
  if(o==='*')return a*b;if(o==='/')return b===0?'Error':a/b;
  return b;
}

function cNum(n){
  if(cur==='Error')cur='0';
  if(fresh){cur=n;fresh=false;}
  else{if(cur==='0'&&n!=='0')cur=n;else if(cur!=='0'||n!=='0'){if(cur.replace(/[^0-9]/g,'').length>=15)return;cur+=n;}}
  upd();
}

function cDot(){
  if(fresh){cur='0.';fresh=false;upd();return;}
  if(!cur.includes('.'))cur+='.';
  upd();
}

function cOp(o){
  if(cur==='Error')return;
  if(prev!==null&&!fresh){
    let r=calc(prev,op,cur);
    tape(fmt(prev)+' '+{' + ':'+','-':'−','*':'×','/':'÷'}[o]+ ' '+fmt(parseFloat(cur))+' = '+fmt(r),'op');
    prev=r;cur=String(r);
  }else{
    prev=parseFloat(cur);
  }
  op=o;fresh=true;upd();
}

function cEq(){
  if(cur==='Error')return;
  if(prev!==null&&op){
    let r=calc(prev,op,cur);
    const sym={'+':'+','-':'−','*':'×','/':'÷'};
    tape(fmt(prev)+' '+sym[op]+' '+fmt(parseFloat(cur))+' = '+fmt(r),'op');
    cur=String(r);prev=null;op=null;fresh=true;upd();
  }
}

function cClear(){
  cur='0';prev=null;op=null;fresh=true;
  $t.innerHTML='';hist=[];upd();
}

function cSign(){
  if(cur==='Error'||cur==='0')return;
  cur=cur.startsWith('-')?cur.slice(1):'-'+cur;
  fresh=true;upd();
}

function cRate(r){
  vatR=r;
  document.querySelectorAll('.controls .sep~.btn-vat:not(:last-child)').forEach(b=>b.classList.remove('active'));
  event.target.classList.add('active');
  tape('VAT rate → '+r+'%','');
}

function cVat(mode){
  if(cur==='Error')return;
  let n=parseFloat(cur);if(isNaN(n))return;
  let tax,res;
  if(mode==='add'){
    tax=n*(vatR/100);res=n+tax;
    tape(fmt(n)+' + '+vatR+'% VAT ('+fmt(tax)+') = '+fmt(res),'vat-add');
  }else{
    tax=n-(n/(1+vatR/100));res=n-tax;
    tape(fmt(n)+' − '+vatR+'% VAT ('+fmt(tax)+') = '+fmt(res),'vat-sub');
  }
  cur=String(res);prev=null;op=null;fresh=true;upd();
}

upd();
</script>
</body>
</html>
