.keypad{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:6px 10px;flex-shrink:0;}
.btn{border:none;border-radius:50%;height:48px;font-size:20px;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:filter .1s;user-select:none;}
.btn:active{filter:brightness(1.4);}
