</head>
<body>
<div class="phone"><div class="screen">
<div class="status-bar">Bookkeeping Calc</div>
<div class="tabs" id="tabs"></div>
<div class="display-area">
<div class="total-label" id="totalLabel">Personal</div>
<div class="expression" id="expression">&nbsp;</div>
<div class="current-value" id="display">0</div>
</div>
<div class="keypad" id="keypad"></div>
<div class="history-panel" id="historyPanel">
<div class="hist-header"><h2 id="histTitle">History</h2><button class="hist-close" onclick="toggleHistory()">Done</button></div>
<div class="hist-list" id="histList"></div>
</div>
<div class="modal-overlay" id="modal">
<div class="modal">
<h3>New Running Total</h3>
<input type="text" id="newName" placeholder="e.g. Groceries" maxlength="16">
<div class="modal-btns">
<button class="modal-cancel" onclick="closeModal()">Cancel</button>
<button class="modal-confirm" onclick="addTotal()">Create</button>
</div>
</div>
</div>
</div></div>

<script>
const state = {
  totals: [
    { id: 1, name: 'Personal', value: 0, history: [
      { expr: 'Starting balance', result: 0 }
    ]},
    { id: 2, name: 'Business', value: 0, history: [] }
  ],
  activeId: 1,
  input: '0',
  operator: null,
  operand: null,
  freshResult: false,
  nextId: 3
};

function getActive() { return state.totals.find(t => t.id === state.activeId); }

function renderTabs() {
  const el = document.getElementById('tabs');
  let html = '';
  state.totals.forEach(t => {
    html += `<div class="tab ${t.id===state.activeId?'active':''}" onclick="switchTotal(${t.id})">${t.name}</div>`;
  });
  html += `<div class="tab-add" onclick="openModal()">+</div>`;
  el.innerHTML = html;
}

function switchTotal(id) {
  state.activeId = id;
  clearCalc();
  renderAll();
}

function renderDisplay() {
  const t = getActive();
  document.getElementById('totalLabel').textContent = t.name + ' — Running Total';
  document.getElementById('display').textContent = formatNum(state.input);
  if (state.operator && state.operand !== null) {
    document.getElementById('expression').textContent = formatNum(String(state.operand)) + ' ' + opSymbol(state.operator);
  } else {
    document.getElementById('expression').innerHTML = '&nbsp;';
  }
}

function formatNum(s) {
  if (s === 'Error') return 'Error';
  let n = parseFloat(s);
  if (isNaN(n)) return s;
  let parts = s.split('.');
  let intPart = parts[0];
  let sign = intPart.startsWith('-') ? '-' : '';
  intPart = intPart.replace('-', '');
  intPart = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  let res = sign + intPart;
  if (parts.length > 1) res += '.' + parts[1];
  return res;
}

function opSymbol(op) {
  return { '+': '+', '-': '−', '*': '×', '/': '÷' }[op] || op;
}

function buildKeypad() {
  const keys = [
    { label: 'C', type: 'fn', action: 'clear' },
    { label: '±', type: 'fn', action: 'negate' },
    { label: '%', type: 'fn', action: 'percent' },
    { label: '÷', type: 'op', action: '/' },
    { label: '7', type: 'num' }, { label: '8', type: 'num' }, { label: '9', type: 'num' },
    { label: '×', type: 'op', action: '*' },
    { label: '4', type: 'num' }, { label: '5', type: 'num' }, { label: '6', type: 'num' },
    { label: '−', type: 'op', action: '-' },
    { label: '1', type: 'num' }, { label: '2', type: 'num' }, { label: '3', type: 'num' },
    { label: '+', type: 'op', action: '+' },
    { label: '0', type: 'num', zero: true },
    { label: '.', type: 'num' },
    { label: '=', type: 'op', action: '=' }
  ];
  const el = document.getElementById('keypad');
  el.innerHTML = '';
  keys.forEach(k => {
    const btn = document.createElement('button');
    let cls = 'btn ';
    if (k.type === 'num') cls += 'btn-num';
    else if (k.type === 'op') cls += 'btn-op';
    else cls += 'btn-fn';
    if (k.zero) cls += ' btn-zero';
    if (k.type === 'op' && k.action === state.operator && !state.freshResult) cls += ' active-op';
    btn.className = cls;
    btn.textContent = k.label;
    btn.onclick = () => handleKey(k);
    el.appendChild(btn);
  });
}

function handleKey(k) {
  if (k.type === 'num') {
    if (k.label === '.') {
      if (state.freshResult) { state.input = '0.'; state.freshResult = false; }
      else if (!state.input.includes('.')) state.input += '.';
    } else {
      if (state.input === '0' || state.freshResult) { state.input = k.label; state.freshResult = false; }
      else if (state.input.replace(/[^0-9]/g,'').length < 12) state.input += k.label;
    }
  } else if (k.type === 'op') {
    if (k.action === '=') { calculate(); }
    else { setOperator(k.action); }
  } else if (k.action === 'clear') { clearCalc(); }
  else if (k.action === 'negate') {
    if (state.input !== '0') {
      state.input = state.input.startsWith('-') ? state.input.slice(1) : '-' + state.input;
    }
  } else if (k.action === 'percent') {
    let v = parseFloat(state.input) / 100;
    state.input = String(v);
    state.freshResult = true;
  }
  renderAll();
}

function setOperator(op) {
  if (state.operator && !state.freshResult) { calculate(true); }
  state.operand = parseFloat(state.input);
  state.operator = op;
  state.freshResult = true;
}

function calculate(chaining) {
  if (state.operator === null || state.operand === null) return;
  const b = parseFloat(state.input);
  const a = state.operand;
  let result;
  const sym = opSymbol(state.operator);
  switch (state.operator) {
    case '+': result = a + b; break;
    case '-': result = a - b; break;
    case '*': result = a * b; break;
    case '/': result = b === 0 ? 'Error' : a / b; break;
  }
  const exprStr = `${formatNum(String(a))} ${sym} ${formatNum(String(b))}`;
  if (result === 'Error') {
    state.input = 'Error';
  } else {
    result = Math.round(result * 1e10) / 1e10;
    state.input = String(result);
    const t = getActive();
    t.value = result;
    t.history.push({ expr: exprStr, result: result });
  }
  if (!chaining) {
    state.operator = null;
    state.operand = null;
  }
  state.freshResult = true;
}

function clearCalc() {
  const t = getActive();
  state.input = String(t.value);
  state.operator = null;
  state.operand = null;
  state.freshResult = false;
}

function toggleHistory() {
  const p = document.getElementById('historyPanel');
  p.classList.toggle('open');
  if (p.classList.contains('open')) renderHistory();
}

function renderHistory() {
  const t = getActive();
  document.getElementById('histTitle').textContent = t.name + ' History';
  const el = document.getElementById('histList');
  if (t.history.length === 0) {
    el.innerHTML = '<div class="hist-empty">No calculations yet</div>';
    return;
  }
  el.innerHTML = [...t.history].reverse().map(h =>
    `<div class="hist-item"><span class="hist-expr">${h.expr}</span><span class="hist-result">= ${formatNum(String(h.result))}</span></div>`
  ).join('');
}

function openModal() { document.getElementById('modal').classList.add('open'); document.getElementById('newName').value=''; document.getElementById('newName').focus(); }
function closeModal() { document.getElementById('modal').classList.remove('open'); }
function addTotal() {
  const name = document.getElementById('newName').value.trim() || ('Total ' + state.nextId);
  state.totals.push({ id: state.nextId++, name, value: 0, history: [] });
  state.activeId = state.nextId - 1;
  clearCalc();
  closeModal();
  renderAll();
}

function renderAll() { renderTabs(); renderDisplay(); buildKeypad(); }

// Add history button to status bar area
document.querySelector('.status-bar').innerHTML = '<span style="flex:1;text-align:left;padding-left:16px;cursor:pointer;font-size:13px;" onclick="toggleHistory()">📋 History</span><span>Bookkeeping Calc</span><span style="flex:1"></span>';
document.querySelector('.status-bar').style.justifyContent = 'space-between';

renderAll();
</script>
</body>
</html>
