.btn-confirm{background:#ffd60a;color:#000}
</style>
</head>
<body>
<div class="phone">
  <div class="status-bar"><span>9:41</span><span>⚡ 📶</span></div>
  <div class="tabs">
    <button class="tab-btn active" onclick="switchTab('calc')">计算器</button>
    <button class="tab-btn" onclick="switchTab('history')">历史记录</button>
  </div>
  <div id="calcView">
    <div class="total-selector" id="totalSelector"></div>
    <div class="display-area">
      <div class="display-expr" id="displayExpr"></div>
      <div class="display-value" id="displayValue">0</div>
    </div>
    <div class="rate-row">
      <span class="rate-label">汇率 (USD→CNY):</span>
      <input type="number" class="rate-input" id="rateInput" value="7.25" step="0.01" min="0" oninput="updateRate()">
    </div>
    <div class="rate-convert" id="rateConvert"></div>
    <div class="keypad" id="keypad"></div>
  </div>
  <div class="history-panel" id="historyPanel">
    <div class="history-header">
      <h2 id="historyTitle">历史记录</h2>
      <button class="close-btn" onclick="switchTab('calc')">完成</button>
    </div>
    <div class="history-list" id="historyList"></div>
  </div>
  <div class="modal-overlay" id="modal">
    <div class="modal">
      <h3>新建账本</h3>
      <input type="text" id="newTotalName" placeholder="输入名称，如：餐饮、交通…" maxlength="10">
      <div class="modal-btns">
        <button class="btn-cancel" onclick="closeModal()">取消</button>
        <button class="btn-confirm" onclick="addTotal()">创建</button>
      </div>
    </div>
  </div>
</div>

<script>
let totals = [
  {id:1,name:'日常开支',value:0,history:[]},
  {id:2,name:'业务收入',value:0,history:[]}
];
let activeId = 1;
let currentInput = '0';
let pendingOp = null;
let operand = 0;
let resetNext = false;
let exchangeRate = 7.25;
let nextId = 3;

function getActive(){ return totals.find(t=>t.id===activeId) }

function renderTotals(){
  const c = document.getElementById('totalSelector');
  let h = '';
  totals.forEach(t=>{
    h += `<button class="total-chip ${t.id===activeId?'active':''}" onclick="selectTotal(${t.id})">${t.name}</button>`;
  });
  h += `<button class="add-total-btn" onclick="openModal()">+</button>`;
  c.innerHTML = h;
}

function selectTotal(id){
  activeId = id;
  currentInput = String(getActive().value);
  pendingOp = null;
  resetNext = false;
  renderTotals();
  updateDisplay();
}

function updateDisplay(){
  const t = getActive();
  const dv = document.getElementById('displayValue');
  const de = document.getElementById('displayExpr');
  const rc = document.getElementById('rateConvert');

  let displayNum = parseFloat(currentInput) || 0;
  dv.textContent = formatNum(displayNum);

  if(pendingOp){
    de.textContent = `${formatNum(operand)} ${opSymbol(pendingOp)}`;
  } else {
    de.textContent = '';
  }

  if(t.value !== 0){
    const converted = t.value * exchangeRate;
    rc.textContent = `≈ ¥${formatNum(converted)} CNY`;
  } else {
    rc.textContent = '';
  }

  // highlight active op
  document.querySelectorAll('.key-op').forEach(b=>{
    b.classList.remove('active-op');
    if(pendingOp && b.dataset.op === pendingOp) b.classList.add('active-op');
  });
}

function formatNum(n){
  if(Number.isNaN(n)||!Number.isFinite(n)) return 'Error';
  let s = n.toFixed(2);
  if(s.endsWith('.00')) s = s.slice(0,-3);
  else if(s.endsWith('0')&&s.includes('.')) s = s.slice(0,-1);
  let parts = s.split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');
  return parts.join('.');
}

function opSymbol(op){
  return {'+':'+','-':'−','*':'×','/':'÷'}[op]||op;
}

function buildKeypad(){
  const keys = [
    {l:'AC',t:'func',a:'clear'},{l:'±',t:'func',a:'negate'},{l:'%',t:'func',a:'percent'},{l:'÷',t:'op',a:'/'}  ,
    {l:'7',t:'num',a:'7'},{l:'8',t:'num',a:'8'},{l:'9',t:'num',a:'9'},{l:'×',t:'op',a:'*'},
    {l:'4',t:'num',a:'4'},{l:'5',t:'num',a:'5'},{l:'6',t:'num',a:'6'},{l:'−',t:'op',a:'-'},
    {l:'1',t:'num',a:'1'},{l:'2',t:'num',a:'2'},{l:'3',t:'num',a:'3'},{l:'+',t:'op',a:'+'},
    {l:'0',t:'num zero',a:'0'},{l:'.',t:'num',a:'.'},{l:'=',t:'op eq',a:'='}
  ];
  const kp = document.getElementById('keypad');
  kp.innerHTML = '';
  keys.forEach(k=>{
    const b = document.createElement('button');
    let cls = 'key ';
    if(k.t.includes('func')) cls += 'key-func';
    else if(k.t.includes('op')) cls += 'key-op';
    else cls += 'key-num';
    if(k.t.includes('zero')) cls += ' key-zero';
    if(k.t.includes('eq')){ b.style.background='#30d158';b.style.color='#000'; }
    b.className = cls;
    b.textContent = k.l;
    if(k.t.includes('op')&&!k.t.includes('eq')) b.dataset.op = k.a;
    b.onclick = ()=>handleKey(k.a,k.t);
    kp.appendChild(b);
  });
}

function handleKey(action, type){
  if(type==='num'){
    if(action==='.'){
      if(resetNext){currentInput='0.';resetNext=false;}
      else if(!currentInput.includes('.')) currentInput+='.';
    } else {
      if(currentInput==='0'||resetNext){currentInput=action;resetNext=false;}
      else currentInput+=action;
    }
  } else if(type==='func'){
    if(action==='clear'){
      currentInput='0';pendingOp=null;operand=0;resetNext=false;
    } else if(action==='negate'){
      let v=parseFloat(currentInput)||0;
      currentInput=String(-v);
    } else if(action==='percent'){
      let v=parseFloat(currentInput)||0;
      currentInput=String(v/100);
    }
  } else if(type==='op'){
    let v = parseFloat(currentInput)||0;
    if(action==='='){
      if(pendingOp){
        let result = calc(operand,pendingOp,v);
        let expr = `${formatNum(operand)} ${opSymbol(pendingOp)} ${formatNum(v)} = ${formatNum(result)}`;
        getActive().history.unshift({expr,result,time:new Date().toLocaleTimeString()});
        getActive().value = result;
        currentInput = String(result);
        pendingOp = null;
        resetNext = true;
      }
    } else {
      if(pendingOp && !resetNext){
        let result = calc(operand,pendingOp,v);
        getActive().value = result;
        currentInput = String(result);
        operand = result;
      } else {
        operand = v;
        getActive().value = v;
      }
      pendingOp = action;
      resetNext = true;
    }
  }
  updateDisplay();
}

function calc(a,op,b){
  switch(op){
    case '+':return a+b;
    case '-':return a-b;
    case '*':return a*b;
    case '/':return b===0?0:a/b;
  }
  return 0;
}

function updateRate(){
  let v = parseFloat(document.getElementById('rateInput').value);
  if(!isNaN(v)&&v>0) exchangeRate=v;
  updateDisplay();
}

function switchTab(tab){
  document.querySelectorAll('.tab-btn').forEach((b,i)=>{
    b.classList.toggle('active', (i===0&&tab==='calc')||(i===1&&tab==='history'));
  });
  document.getElementById('calcView').style.display = tab==='calc'?'block':'none';
  const hp = document.getElementById('historyPanel');
  if(tab==='history'){
    hp.classList.add('show');
    renderHistory();
  } else {
    hp.classList.remove('show');
  }
}

function renderHistory(){
  const t = getActive();
  document.getElementById('historyTitle').textContent = `${t.name} - 历史记录`;
  const list = document.getElementById('historyList');
  if(t.history.length===0){
    list.innerHTML='<div class="history-empty">暂无计算记录</div>';
    return;
  }
  list.innerHTML = t.history.map(h=>`
    <div class="history-item">
      <div>
        <div class="history-expr">${h.expr}</div>
        <div style="font-size:11px;color:#555;margin-top:2px">${h.time}</div>
      </div>
      <div class="history-result">${formatNum(h.result)}</div>
    </div>
  `).join('');
}

function openModal(){document.getElementById('modal').classList.add('show');document.getElementById('newTotalName').value='';document.getElementById('newTotalName').focus();}
function closeModal(){document.getElementById('modal').classList.remove('show');}
function addTotal(){
  let name=document.getElementById('newTotalName').value.trim();
  if(!name) name=`账本${nextId}`;
  totals.push({id:nextId++,name,value:0,history:[]});
  closeModal();
  selectTotal(nextId-1);
}

// init
renderTotals();
buildKeypad();
updateDisplay();
</script>
</body>
</html>
