<title>Egg Timer</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#fef9ef;color:#2d2a26;display:flex;justify-content:center;align-items:center;min-height:100vh;overflow:hidden}
.app{width:100%;max-width:420px;height:520px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;position:relative;border-radius:24px;background:#fff;box-shadow:0 8px 40px rgba(0,0,0,.08)}
h1{font-size:1.3rem;font-weight:700;margin-bottom:4px;letter-spacing:-.02em}
