.ctrl-btn:active{transform:scale(.96)}
#startBtn{background:#e07b3c;color:#fff}
#startBtn:hover{background:#c96a2f}
#startBtn:disabled{background:#ddd;color:#aaa;cursor:default;transform:none}
#stopBtn{background:#f0ebe3;color:#6b6560;display:none}
#stopBtn:hover{background:#e4ddd3}
.flash-overlay{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:999;opacity:0}
.flash-overlay.active{animation:flashAnim .45s ease-in-out infinite alternate;pointer-events:auto}
@keyframes flashAnim{0%{opacity:0;background:#ff4444}100%{opacity:.35;background:#ff4444}}
.done-state .display{color:#e07b3c}
.wake-badge{position:absolute;top:16px;right:16px;font-size:.65rem;background:#e8f5e9;color:#388e3c;padding:3px 8px;border-radius:6px;display:none;font-weight:600}
