<body>
<div class="app" id="app">
  <div class="wake-badge" id="wakeBadge">☀ Screen awake</div>
  <h1>🥚 Egg Timer</h1>
  <p class="subtitle">Pick a preset and start cooking</p>
  <div class="presets" id="presets">
    <button class="preset-btn selected" data-seconds="240">
      <div class="time">4 min</div>
      <div class="label">Soft</div>
    </button>
    <button class="preset-btn" data-seconds="420">
      <div class="time">7 min</div>
      <div class="label">Medium</div>
    </button>
    <button class="preset-btn" data-seconds="600">
      <div class="time">10 min</div>
      <div class="label">Hard</div>
    </button>
  </div>
  <div class="display" id="display">4:00</div>
  <div class="status" id="status">Ready</div>
  <div class="controls">
    <button class="ctrl-btn" id="startBtn">Start</button>
    <button class="ctrl-btn" id="stopBtn">Stop</button>
  </div>
</div>
<div class="flash-overlay" id="flashOverlay"></div>

<script>
(function(){
  const display = document.getElementById('display');
  const status = document.getElementById('status');
  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');
  const flashOverlay = document.getElementById('flashOverlay');
  const app = document.getElementById('app');
  const wakeBadge = document.getElementById('wakeBadge');
  const presetBtns = document.querySelectorAll('.preset-btn');

  let totalSeconds = 240;
  let remainingMs = totalSeconds * 1000;
  let timerInterval = null;
  let endTime = null;
  let isRunning = false;
  let isDone = false;
  let audioCtx = null;
  let beepInterval = null;
  let wakeLock = null;

  // Preset selection
  presetBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      if (isRunning) return;
      presetBtns.forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      totalSeconds = parseInt(btn.dataset.seconds);
      remainingMs = totalSeconds * 1000;
      isDone = false;
      app.classList.remove('done-state');
      updateDisplay();
      status.textContent = 'Ready';
      status.style.color = '#aaa';
    });
  });

  function formatTime(ms) {
    const s = Math.max(0, Math.ceil(ms / 1000));
    const m = Math.floor(s / 60);
    const sec = s % 60;
    return m + ':' + (sec < 10 ? '0' : '') + sec;
  }

  function updateDisplay() {
    display.textContent = formatTime(remainingMs);
  }

  // Wake Lock API
  async function requestWakeLock() {
    try {
      if ('wakeLock' in navigator) {
        wakeLock = await navigator.wakeLock.request('screen');
        wakeBadge.classList.add('show');
        wakeLock.addEventListener('release', () => {
          wakeBadge.classList.remove('show');
        });
      }
    } catch(e) {}
  }

  function releaseWakeLock() {
    if (wakeLock) {
      wakeLock.release();
      wakeLock = null;
      wakeBadge.classList.remove('show');
    }
  }

  // Re-acquire wake lock when tab becomes visible again
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible' && isRunning) {
      requestWakeLock();
      // Recalculate remaining time based on endTime
      if (endTime) {
        remainingMs = endTime - Date.now();
        if (remainingMs <= 0) {
          remainingMs = 0;
          completeTimer();
        } else {
          updateDisplay();
        }
      }
    }
  });

  // Audio beep using Web Audio API
  function playBeep() {
    try {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.type = 'square';
      osc.frequency.value = 880;
      gain.gain.value = 0.5;
      osc.start();
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.25);
      osc.stop(audioCtx.currentTime + 0.3);
    } catch(e){}
  }

  function startAlarm() {
    playBeep();
    beepInterval = setInterval(playBeep, 500);
    flashOverlay.classList.add('active');
  }

  function stopAlarm() {
    if (beepInterval) { clearInterval(beepInterval); beepInterval = null; }
    flashOverlay.classList.remove('active');
  }

  function completeTimer() {
    isRunning = false;
    isDone = true;
    clearInterval(timerInterval);
    timerInterval = null;
    remainingMs = 0;
    updateDisplay();
    status.textContent = 'Done! Tap Stop to dismiss';
    status.style.color = '#e07b3c';
    app.classList.add('done-state');
    startBtn.style.display = 'none';
    stopBtn.style.display = 'inline-block';
    stopBtn.textContent = 'Dismiss';
    startAlarm();
    releaseWakeLock();
  }

  // Start
  startBtn.addEventListener('click', () => {
    if (isRunning || isDone) return;
    isRunning = true;
    endTime = Date.now() + remainingMs;
    status.textContent = 'Cooking…';
    status.style.color = '#e07b3c';
    startBtn.style.display = 'none';
    stopBtn.style.display = 'inline-block';
    stopBtn.textContent = 'Stop';
    requestWakeLock();

    timerInterval = setInterval(() => {
      remainingMs = endTime - Date.now();
      if (remainingMs <= 0) {
        completeTimer();
      } else {
        updateDisplay();
      }
    }, 100);
  });

  // Stop / Dismiss
  stopBtn.addEventListener('click', () => {
    if (isDone) {
      // Dismiss alarm
      stopAlarm();
      isDone = false;
      app.classList.remove('done-state');
      remainingMs = totalSeconds * 1000;
      updateDisplay();
      status.textContent = 'Ready';
      status.style.color = '#aaa';
      stopBtn.style.display = 'none';
      startBtn.style.display = 'inline-block';
      return;
    }
    if (isRunning) {
      clearInterval(timerInterval);
      timerInterval = null;
      isRunning = false;
      remainingMs = Math.max(0, endTime - Date.now());
      endTime = null;
      updateDisplay();
      status.textContent = 'Paused';
      status.style.color = '#aaa';
      stopBtn.style.display = 'none';
      startBtn.style.display = 'inline-block';
      releaseWakeLock();
    }
  });

  // Service Worker registration (inline for offline PWA support)
  if ('serviceWorker' in navigator) {
    const swCode = `
      const CACHE='egg-timer-v1';
      self.addEventListener('install',e=>{self.skipWaiting();});
      self.addEventListener('activate',e=>{e.waitUntil(clients.claim());});
      self.addEventListener('fetch',e=>{
        e.respondWith(
          caches.match(e.request).then(r=>r||fetch(e.request).then(res=>{
            if(res.status===200){const c=res.clone();caches.open(CACHE).then(cache=>cache.put(e.request,c));}
            return res;
          }).catch(()=>new Response('Offline',{headers:{'Content-Type':'text/plain'}})))
        );
      });
    `;
    const blob = new Blob([swCode], {type:'application/javascript'});
    navigator.serviceWorker.register(URL.createObjectURL(blob)).catch(()=>{});
  }

  updateDisplay();
})();
</script>
</body>
</html>
