<script>
const COLORS={Jamie:'#e06c75',Alex:'#61afef',Sam:'#98c379',Taylor:'#c678dd',Jordan:'#e5c07b'};
let tasks=[
{id:1,title:'Create GitHub Project linked to harness repo',assignee:'Jamie',due:'2025-01-20',status:'done'},
{id:2,title:'Configure To Do / In Progress / Done columns',assignee:'Jamie',due:'2025-01-20',status:'done'},
{id:3,title:'Document assignee & due date requirements',assignee:'Alex',due:'2025-01-21',status:'inprogress'},
{id:4,title:'Populate board with current team tasks',assignee:'Sam',due:'2025-01-22',status:'inprogress'},
{id:5,title:'Send workflow announcement to team chat',assignee:'Taylor',due:'2025-01-23',status:'todo'},
{id:6,title:'Set up harness CI pipeline config',assignee:'Jordan',due:'2025-01-25',status:'todo'},
{id:7,title:'Write README usage guidelines',assignee:'Alex',due:'2025-01-24',status:'todo'}
];
let nextId=8;
const COLUMNS=[
{key:'todo',label:'To Do'},
{key:'inprogress',label:'In Progress'},
{key:'done',label:'Done'}
];

function render(){
const board=document.getElementById('board');
board.innerHTML='';
COLUMNS.forEach(col=>{
const colTasks=tasks.filter(t=>t.status===col.key);
const div=document.createElement('div');
div.className='column';
div.innerHTML=`<div class="col-header"><span>${col.label}</span><span class="col-count">${colTasks.length}</span></div>`;
const body=document.createElement('div');
body.className='col-body';
colTasks.forEach(t=>{
const today=new Date();today.setHours(0,0,0,0);
const dueDate=new Date(t.due+'T00:00:00');
const overdue=dueDate<today&&t.status!=='done';
const card=document.createElement('div');
card.className='card';
card.onclick=()=>moveTask(t.id);
const initials=t.assignee.slice(0,2).toUpperCase();
const color=COLORS[t.assignee]||'#8b949e';
card.innerHTML=`<div class="card-title">${esc(t.title)}</div><div class="card-meta"><span class="assignee"><span class="avatar" style="background:${color}">${initials}</span>${esc(t.assignee)}</span><span class="due ${overdue?'overdue':''}"><svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor"><path d="M4.75 0a.75.75 0 01.75.75V2h5V.75a.75.75 0 011.5 0V2h1.25c.966 0 1.75.784 1.75 1.75v10.5A1.75 1.75 0 0113.25 16H2.75A1.75 1.75 0 011 14.25V3.75C1 2.784 1.784 2 2.75 2H4V.75A.75.75 0 014.75 0zM2.5 7.5v6.75c0 .138.112.25.25.25h10.5a.25.25 0 00.25-.25V7.5zm11-1.5v-2.25a.25.25 0 00-.25-.25H2.75a.25.25 0 00-.25.25V6z"/></svg>${formatDate(t.due)}</span></div>`;
body.appendChild(card);
});
div.appendChild(body);
board.appendChild(div);
});
}

function esc(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}
function formatDate(d){const dt=new Date(d+'T00:00:00');return dt.toLocaleDateString('en-US',{month:'short',day:'numeric'})}

function openModal(){
document.getElementById('modalOverlay').classList.add('active');
document.getElementById('taskTitle').value='';
document.getElementById('taskAssignee').value='';
document.getElementById('taskDue').value='';
document.getElementById('taskStatus').value='todo';
document.getElementById('errorMsg').style.display='none';
document.getElementById('taskTitle').focus();
}
function closeModal(){document.getElementById('modalOverlay').classList.remove('active')}

function saveTask(){
const title=document.getElementById('taskTitle').value.trim();
const assignee=document.getElementById('taskAssignee').value;
const due=document.getElementById('taskDue').value;
const status=document.getElementById('taskStatus').value;
if(!title||!assignee||!due){
document.getElementById('errorMsg').style.display='block';
return;
}
tasks.push({id:nextId++,title,assignee,due,status});
closeModal();
render();
showToast('Task added successfully');
}

function moveTask(id){
const t=tasks.find(x=>x.id===id);
if(!t)return;
const order=['todo','inprogress','done'];
const labels={'todo':'To Do','inprogress':'In Progress','done':'Done'};
const idx=order.indexOf(t.status);
const next=order[(idx+1)%3];
if(confirm(`Move "${t.title}" to ${labels[next]}?`)){
t.status=next;
render();
showToast(`Moved to ${labels[next]}`);
}
}

function showToast(msg){
const el=document.getElementById('toast');
el.textContent=msg;
el.classList.add('show');
setTimeout(()=>el.classList.remove('show'),2000);
}

render();
</script>
