<script>
const COLORS = {Alex:'#e74c3c',Sam:'#3498db',Jordan:'#2ecc71',Taylor:'#9b59b6',Casey:'#e67e22'};
let cards = [
  {id:1,title:'Define project scope & user stories',assignee:'Alex',desc:'Outline what we are building this weekend.',col:'todo'},
  {id:2,title:'Set up shared repo & branch strategy',assignee:'Sam',desc:'',col:'todo'},
  {id:3,title:'Design landing page wireframe',assignee:'Jordan',desc:'Quick sketch, speed over perfection.',col:'inprogress'},
  {id:4,title:'Configure CI pipeline for demo deploy',assignee:'Taylor',desc:'',col:'inprogress'},
  {id:5,title:'Register team for hackathon',assignee:'Casey',desc:'Done during kickoff.',col:'done'}
];
let nextId = 6;
let dragId = null;

function render(){
  ['todo','inprogress','done'].forEach(col=>{
    const c = document.getElementById('cards-'+col);
    const items = cards.filter(x=>x.col===col);
    document.getElementById('count-'+col).textContent = items.length;
    c.innerHTML = '';
    items.forEach(card=>{
      const el = document.createElement('div');
      el.className = 'card';
      el.draggable = true;
      el.dataset.id = card.id;
      const color = COLORS[card.assignee]||'#95a5a6';
      const init = card.assignee?card.assignee[0]:'?';
      el.innerHTML = `<div class="card-title">${esc(card.title)}</div><div class="card-meta"><span class="assignee">${card.desc?'📝 ':''}<span>${esc(card.assignee||'Unassigned')}</span></span><div class="avatar" style="background:${color}">${init}</div></div>`;
      el.addEventListener('dragstart',e=>{dragId=card.id;el.classList.add('dragging');e.dataTransfer.effectAllowed='move'});
      el.addEventListener('dragend',()=>{el.classList.remove('dragging');dragId=null;document.querySelectorAll('.drop-zone').forEach(z=>z.remove())});
      c.appendChild(el);
    });
    c.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='move';if(!c.querySelector('.drop-zone')){const z=document.createElement('div');z.className='drop-zone';c.appendChild(z)}});
    c.addEventListener('dragleave',e=>{if(!c.contains(e.relatedTarget)){const z=c.querySelector('.drop-zone');if(z)z.remove()}});
    c.addEventListener('drop',e=>{e.preventDefault();const z=c.querySelector('.drop-zone');if(z)z.remove();if(dragId!=null){const card=cards.find(x=>x.id===dragId);if(card){card.col=col;render()}}});
  });
}

function esc(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}

function openModal(col){document.getElementById('cardCol').value=col;document.getElementById('cardTitle').value='';document.getElementById('cardAssignee').value='';document.getElementById('cardDesc').value='';document.getElementById('modalOverlay').classList.add('active');setTimeout(()=>document.getElementById('cardTitle').focus(),50)}
function closeModal(){document.getElementById('modalOverlay').classList.remove('active')}
function saveCard(){
  const t=document.getElementById('cardTitle').value.trim();
  if(!t){showToast('Please enter a card title');return}
  cards.push({id:nextId++,title:t,assignee:document.getElementById('cardAssignee').value,desc:document.getElementById('cardDesc').value.trim(),col:document.getElementById('cardCol').value});
  closeModal();render();showToast('Card added!');
}

function copyLink(){navigator.clipboard&&navigator.clipboard.writeText('https://trello.com/b/hackathon-sprint-demo').then(()=>showToast('Board link copied! Paste it in the group chat.')).catch(()=>showToast('Board link copied! Paste it in the group chat.'));if(!navigator.clipboard)showToast('Board link copied! Paste it in the group chat.')}
function inviteTeam(){showToast('Invite links sent to all hackathon team members (<10) via email!')}
function showToast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');clearTimeout(t._tid);t._tid=setTimeout(()=>t.classList.remove('show'),2800)}

document.getElementById('modalOverlay').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

render();
</script>
</body>
</html>
