<div class="app">
  <div class="header">
    <h1>BEAT MAKER</h1>
    <button class="btn btn-play" id="playBtn">▶ Play</button>
    <button class="btn btn-clear" id="clearBtn">Clear</button>
    <div class="tempo">
      <span>BPM</span>
      <input type="range" id="bpmSlider" min="60" max="200" value="120">
