<script>
(function(){
  const STEPS = 16, TRACKS = 4;
  const NAMES = ['Kick','Snare','Hi-Hat','Melody'];
  let pattern = Array.from({length:TRACKS}, ()=> new Array(STEPS).fill(false));
  let playing = false, currentStep = -1, bpm = 120;
  let timerID = null, nextNoteTime = 0, ctx = null, analyser = null, masterGain = null;

  // --- Audio Engine ---
  function initAudio(){
    if(ctx) return;
    ctx = new (window.AudioContext || window.webkitAudioContext)();
    masterGain = ctx.createGain();
    masterGain.gain.value = 0.8;
    analyser = ctx.createAnalyser();
    analyser.fftSize = 2048;
    masterGain.connect(analyser);
    analyser.connect(ctx.destination);
  }

  function playKick(t){
    const o = ctx.createOscillator(), g = ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(150, t);
    o.frequency.exponentialRampToValueAtTime(30, t + 0.12);
    g.gain.setValueAtTime(1, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
    o.connect(g); g.connect(masterGain);
    o.start(t); o.stop(t + 0.35);
  }

  function playSnare(t){
    const len = 0.15, buf = ctx.createBuffer(1, ctx.sampleRate * len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1);
    const n = ctx.createBufferSource(); n.buffer = buf;
    const nf = ctx.createBiquadFilter(); nf.type='highpass'; nf.frequency.value=1000;
    const ng = ctx.createGain(); ng.gain.setValueAtTime(0.7,t); ng.gain.exponentialRampToValueAtTime(0.001,t+len);
    n.connect(nf); nf.connect(ng); ng.connect(masterGain); n.start(t); n.stop(t+len);
    const o = ctx.createOscillator(), og = ctx.createGain();
    o.type='triangle'; o.frequency.setValueAtTime(180,t); o.frequency.exponentialRampToValueAtTime(60,t+0.08);
    og.gain.setValueAtTime(0.6,t); og.gain.exponentialRampToValueAtTime(0.001,t+0.08);
    o.connect(og); og.connect(masterGain); o.start(t); o.stop(t+0.1);
  }

  function playHihat(t){
    const len=0.06, buf=ctx.createBuffer(1,ctx.sampleRate*len,ctx.sampleRate);
    const d=buf.getChannelData(0);
    for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1);
    const n=ctx.createBufferSource(); n.buffer=buf;
    const f=ctx.createBiquadFilter(); f.type='highpass'; f.frequency.value=7000;
    const g=ctx.createGain(); g.gain.setValueAtTime(0.35,t); g.gain.exponentialRampToValueAtTime(0.001,t+len);
    n.connect(f); f.connect(g); g.connect(masterGain); n.start(t); n.stop(t+len);
  }

  function playMelodic(t){
    const o=ctx.createOscillator(), g=ctx.createGain();
    o.type='square'; o.frequency.setValueAtTime(261.63,t);
    g.gain.setValueAtTime(0.2,t); g.gain.setValueAtTime(0.2,t+0.06); g.gain.exponentialRampToValueAtTime(0.001,t+0.22);
    o.connect(g); g.connect(masterGain); o.start(t); o.stop(t+0.25);
  }

  const synths = [playKick, playSnare, playHihat, playMelodic];

  // --- Sequencer Scheduling ---
  const scheduleAhead = 0.1, lookahead = 25;

  function scheduler(){
    while(nextNoteTime < ctx.currentTime + scheduleAhead){
      for(let tr=0;tr<TRACKS;tr++){
        if(pattern[tr][currentStep]) synths[tr](nextNoteTime);
      }
      scheduleUI(currentStep);
      advance();
    }
  }

  function advance(){
    const spb = 60.0 / bpm / 4;
    nextNoteTime += spb;
    currentStep = (currentStep + 1) % STEPS;
  }

  function scheduleUI(step){
    setTimeout(()=>{
      highlightStep(step);
    }, (nextNoteTime - ctx.currentTime) * 1000);
  }

  function startStop(){
    initAudio();
    if(ctx.state==='suspended') ctx.resume();
    if(playing){
      playing=false; clearInterval(timerID); currentStep=-1;
      document.getElementById('playBtn').textContent='▶ Play';
      document.getElementById('playBtn').classList.remove('active');
      clearHighlight();
    } else {
      playing=true; currentStep=0; nextNoteTime=ctx.currentTime;
      timerID=setInterval(scheduler, lookahead);
      document.getElementById('playBtn').textContent='■ Stop';
      document.getElementById('playBtn').classList.add('active');
    }
  }

  // --- UI ---
  const gridEl = document.getElementById('grid');
  const stepEls = [];

  function buildGrid(){
    for(let tr=0;tr<TRACKS;tr++){
      const lbl=document.createElement('div');
      lbl.className='track-label'; lbl.textContent=NAMES[tr];
      gridEl.appendChild(lbl);
      stepEls[tr]=[];
      for(let s=0;s<STEPS;s++){
        const btn=document.createElement('div');
        btn.className='step'; btn.dataset.t=tr; btn.dataset.s=s;
        btn.addEventListener('click',()=>toggleStep(tr,s));
        gridEl.appendChild(btn);
        stepEls[tr][s]=btn;
      }
    }
    // beat marks
    const bm=document.getElementById('beatMarks');
    const spacer=document.createElement('div'); bm.appendChild(spacer);
    for(let s=0;s<STEPS;s++){
      const m=document.createElement('div');
      m.className='beat-mark'+(s%4===0?' down':'');
      bm.appendChild(m);
    }
  }

  function toggleStep(tr,s){
    initAudio();
    pattern[tr][s]=!pattern[tr][s];
    stepEls[tr][s].classList.toggle('on', pattern[tr][s]);
    if(pattern[tr][s] && !playing) synths[tr](ctx.currentTime);
  }

  function highlightStep(step){
    clearHighlight();
    for(let tr=0;tr<TRACKS;tr++) stepEls[tr][step].classList.add('playing');
  }

  function clearHighlight(){
    for(let tr=0;tr<TRACKS;tr++) for(let s=0;s<STEPS;s++) stepEls[tr][s].classList.remove('playing');
  }

  function clearAll(){
    for(let tr=0;tr<TRACKS;tr++) for(let s=0;s<STEPS;s++){
      pattern[tr][s]=false; stepEls[tr][s].classList.remove('on');
    }
  }

  // --- BPM ---
  const bpmSlider=document.getElementById('bpmSlider');
  const bpmVal=document.getElementById('bpmVal');
  bpmSlider.addEventListener('input',function(){
    bpm=parseInt(this.value); bpmVal.textContent=bpm;
  });

  // --- Visualization ---
  const canvas=document.getElementById('viz');
  const cctx=canvas.getContext('2d');

  function resizeCanvas(){
    const r=canvas.getBoundingClientRect();
    canvas.width=r.width*window.devicePixelRatio;
    canvas.height=r.height*window.devicePixelRatio;
    cctx.scale(window.devicePixelRatio,window.devicePixelRatio);
  }

  function draw(){
    requestAnimationFrame(draw);
    const w=canvas.width/window.devicePixelRatio, h=canvas.height/window.devicePixelRatio;
    cctx.fillStyle='#16162a'; cctx.fillRect(0,0,w,h);
    if(!analyser){
      cctx.strokeStyle='#2a2a4a'; cctx.lineWidth=1;
      cctx.beginPath(); cctx.moveTo(0,h/2); cctx.lineTo(w,h/2); cctx.stroke();
      return;
    }
    const bufLen=analyser.frequencyBinCount;
    const data=new Uint8Array(bufLen);
    analyser.getByteTimeDomainData(data);
    cctx.lineWidth=2; cctx.strokeStyle='#8b5cf6'; cctx.beginPath();
    const sliceW=w/bufLen;
    let x=0;
    for(let i=0;i<bufLen;i++){
      const v=data[i]/128.0, y=v*h/2;
      if(i===0) cctx.moveTo(x,y); else cctx.lineTo(x,y);
      x+=sliceW;
    }
    cctx.lineTo(w,h/2); cctx.stroke();
    // glow effect
    cctx.lineWidth=6; cctx.strokeStyle='rgba(139,92,246,0.15)';
    cctx.beginPath(); x=0;
    for(let i=0;i<bufLen;i++){
      const v=data[i]/128.0, y=v*h/2;
      if(i===0) cctx.moveTo(x,y); else cctx.lineTo(x,y);
      x+=sliceW;
    }
    cctx.stroke();
  }

  // --- Init ---
  buildGrid();
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);
  document.getElementById('playBtn').addEventListener('click', startStop);
  document.getElementById('clearBtn').addEventListener('click', clearAll);
  draw();
})();
</script>
</body>
</html>
