      const o=audioCtx.createOscillator(),g=audioCtx.createGain();
      o.type='sine';o.frequency.setValueAtTime(160,t);o.frequency.exponentialRampToValueAtTime(30,t+.12);
      g.gain.setValueAtTime(1,t);g.gain.exponentialRampToValueAtTime(.001,t+.35);
      o.connect(g);g.connect(masterGain);o.start(t);o.stop(t+.35);break;
    }
    case 'snare':{
      const o=audioCtx.createOscillator(),g=audioCtx.createGain();
      o.type='triangle';o.frequency.setValueAtTime(220,t);o.frequency.exponentialRampToValueAtTime(80,t+.07);
      g.gain.setValueAtTime(.6,t);g.gain.exponentialRampToValueAtTime(.001,t+.12);
      o.connect(g);g.connect(masterGain);o.start(t);o.stop(t+.12);
      const len=audioCtx.sampleRate*.12,buf=audioCtx.createBuffer(1,len,audioCtx.sampleRate),d=buf.getChannelData(0);
      for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/len,2);
      const n=audioCtx.createBufferSource(),ng=audioCtx.createGain(),f=audioCtx.createBiquadFilter();
      n.buffer=buf;f.type='highpass';f.frequency.value=1200;
      ng.gain.setValueAtTime(.7,t);ng.gain.exponentialRampToValueAtTime(.001,t+.12);
      n.connect(f);f.connect(ng);ng.connect(masterGain);n.start(t);break;
    }
    case 'hihat':{
      const len=audioCtx.sampleRate*.06,buf=audioCtx.createBuffer(1,len,audioCtx.sampleRate),d=buf.getChannelData(0);
      for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/len,3);
      const n=audioCtx.createBufferSource(),g=audioCtx.createGain(),f=audioCtx.createBiquadFilter();
      n.buffer=buf;f.type='highpass';f.frequency.value=7000;
      g.gain.setValueAtTime(.35,t);g.gain.exponentialRampToValueAtTime(.001,t+.06);
      n.connect(f);f.connect(g);g.connect(masterGain);n.start(t);break;
    }
    case 'htom':{
      const o=audioCtx.createOscillator(),g=audioCtx.createGain();
      o.type='sine';o.frequency.setValueAtTime(320,t);o.frequency.exponentialRampToValueAtTime(180,t+.1);
      g.gain.setValueAtTime(.75,t);g.gain.exponentialRampToValueAtTime(.001,t+.2);
      o.connect(g);g.connect(masterGain);o.start(t);o.stop(t+.2);break;
    }
    case 'ftom':{
      const o=audioCtx.createOscillator(),g=audioCtx.createGain();
      o.type='sine';o.frequency.setValueAtTime(120,t);o.frequency.exponentialRampToValueAtTime(55,t+.15);
      g.gain.setValueAtTime(.85,t);g.gain.exponentialRampToValueAtTime(.001,t+.3);
      o.connect(g);g.connect(masterGain);o.start(t);o.stop(t+.3);break;
    }
    case 'melo':{
      const notes=[261.63,329.63,392,523.25,392,329.63,293.66,349.23];
      const freq=notes[Math.floor(Math.random()*notes.length)];
      const o=audioCtx.createOscillator(),g=audioCtx.createGain();
      o.type='square';o.frequency.setValueAtTime(freq,t);
      g.gain.setValueAtTime(.18,t);g.gain.setValueAtTime(.18,t+.04);g.gain.exponentialRampToValueAtTime(.001,t+.18);
      o.connect(g);g.connect(masterGain);o.start(t);o.stop(t+.18);break;
    }
  }
}

function scheduler(){
  while(nextStepTime<audioCtx.currentTime+.1){
    tracks.forEach(tr=>{if(pattern[tr.id][currentStep])playSound(tr.id,nextStepTime)});
    scheduleUI(currentStep,nextStepTime);
    const secPerBeat=60/bpm;
    nextStepTime+=secPerBeat/4;
    currentStep=(currentStep+1)%STEPS;
  }
}

function scheduleUI(step,time){
  const delay=Math.max(0,(time-audioCtx.currentTime)*1000);
  setTimeout(()=>{
    document.querySelectorAll('.step.playing').forEach(e=>e.classList.remove('playing'));
    document.querySelectorAll(`.step[data-step="${step}"]`).forEach(e=>e.classList.add('playing'));
  },delay);
}

function start(){
  initAudio();
  if(audioCtx.state==='suspended')audioCtx.resume();
  isPlaying=true;currentStep=0;nextStepTime=audioCtx.currentTime;
  timerID=setInterval(scheduler,25);
  document.getElementById('playBtn').textContent='■ Stop';
  document.getElementById('playBtn').classList.add('active');
}

function stop(){
  isPlaying=false;
  if(timerID){clearInterval(timerID);timerID=null}
  document.querySelectorAll('.step.playing').forEach(e=>e.classList.remove('playing'));
  document.getElementById('playBtn').textContent='▶ Play';
  document.getElementById('playBtn').classList.remove('active');
}

document.getElementById('playBtn').addEventListener('click',()=>{isPlaying?stop():start()});
document.getElementById('clearBtn').addEventListener('click',()=>{
  tracks.forEach(t=>pattern[t.id].fill(false));
  document.querySelectorAll('.step.on').forEach(e=>e.classList.remove('on'));
});
document.getElementById('bpmSlider').addEventListener('input',e=>{
  bpm=parseInt(e.target.value);
  document.getElementById('bpmVal').textContent=bpm;
});

// Build grid
const seqEl=document.getElementById('seq');
tracks.forEach(tr=>{
  const row=document.createElement('div');
  row.className=`row ${tr.cls}`;
  const lbl=document.createElement('div');
  lbl.className='lbl';lbl.textContent=tr.name;
  row.appendChild(lbl);
  const stepsDiv=document.createElement('div');
  stepsDiv.className='steps';
  for(let i=0;i<STEPS;i++){
    const s=document.createElement('div');
    s.className='step'+(i%4===0?' beat-mark':'');
    s.dataset.track=tr.id;s.dataset.step=i;
    s.addEventListener('click',()=>{
      pattern[tr.id][i]=!pattern[tr.id][i];
      s.classList.toggle('on',pattern[tr.id][i]);
      if(pattern[tr.id][i]&&!isPlaying){initAudio();if(audioCtx.state==='suspended')audioCtx.resume();playSound(tr.id,audioCtx.currentTime)}
    });
    stepsDiv.appendChild(s);
  }
  row.appendChild(stepsDiv);
  seqEl.appendChild(row);
});

// Visualization
const canvas=document.getElementById('viz');
const ctx=canvas.getContext('2d');
function resizeCanvas(){
  const r=canvas.getBoundingClientRect();
  canvas.width=r.width*window.devicePixelRatio;
  canvas.height=r.height*window.devicePixelRatio;
  ctx.scale(window.devicePixelRatio,window.devicePixelRatio);
}
resizeCanvas();
window.addEventListener('resize',resizeCanvas);

function draw(){
  requestAnimationFrame(draw);
  const w=canvas.width/window.devicePixelRatio,h=canvas.height/window.devicePixelRatio;
  ctx.clearRect(0,0,w,h);
  if(!analyser){
    ctx.strokeStyle='#252545';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();
    return;
  }
  const bufLen=analyser.frequencyBinCount;
  const dataArr=new Uint8Array(bufLen);
  analyser.getByteTimeDomainData(dataArr);
  ctx.lineWidth=2;ctx.strokeStyle='#00d4ff';ctx.shadowColor='#00d4ff';ctx.shadowBlur=4;
  ctx.beginPath();
  const sliceW=w/bufLen;
  let x=0;
  for(let i=0;i<bufLen;i++){
    const v=dataArr[i]/128.0;
    const y=v*h/2;
    if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
    x+=sliceW;
  }
  ctx.stroke();
  ctx.shadowBlur=0;
}
draw();
